#!/usr/bin/env node
/**
 * generate-firebase-config.mjs
 *
 * Generates public/firebase-config.js at build time from NEXT_PUBLIC_FIREBASE_*
 * environment variables. Run this before `next build`.
 *
 * The generated file is served as a same-origin static asset and imported by
 * firebase-messaging-sw.js via importScripts — no external script-src required.
 *
 * Exit codes:
 *   0 — success
 *   1 — one or more required env vars are missing or still set to PLACEHOLDER
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');

// ── Required public Firebase identifiers ─────────────────────────────────────
// These are safe to ship to the browser. They identify the Firebase project
// but do not grant privileged access on their own.
const REQUIRED_VARS = [
  'NEXT_PUBLIC_FIREBASE_API_KEY',
  'NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN',
  'NEXT_PUBLIC_FIREBASE_PROJECT_ID',
  'NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET',
  'NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID',
  'NEXT_PUBLIC_FIREBASE_APP_ID',
];

const OPTIONAL_VARS = ['NEXT_PUBLIC_FIREBASE_MEASUREMENT_ID'];

const PLACEHOLDER = 'PLACEHOLDER';
const IS_PRODUCTION = process.env.NODE_ENV === 'production';

// ── Validate ──────────────────────────────────────────────────────────────────
const missing = [];
for (const varName of REQUIRED_VARS) {
  const val = process.env[varName];
  if (!val || val === PLACEHOLDER || val.trim() === '') {
    missing.push(varName);
  }
}

if (missing.length > 0) {
  if (IS_PRODUCTION) {
    console.error('\n❌ Production build failed: Firebase config placeholders detected.\n');
    console.error('Missing or placeholder values for:');
    missing.forEach((v) => console.error(`  - ${v}`));
    console.error('\nSet these environment variables before building for production.\n');
    process.exit(1);
  } else {
    console.warn('\n⚠️  Firebase config incomplete (development mode — continuing with placeholders).');
    console.warn('Background messaging will be disabled until real values are provided.\n');
  }
}

// ── Generate ──────────────────────────────────────────────────────────────────
const config = {
  apiKey:            process.env.NEXT_PUBLIC_FIREBASE_API_KEY            ?? PLACEHOLDER,
  authDomain:        process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN        ?? PLACEHOLDER,
  projectId:         process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID         ?? PLACEHOLDER,
  storageBucket:     process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET     ?? PLACEHOLDER,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID ?? PLACEHOLDER,
  appId:             process.env.NEXT_PUBLIC_FIREBASE_APP_ID              ?? PLACEHOLDER,
};

const measurementId = process.env.NEXT_PUBLIC_FIREBASE_MEASUREMENT_ID;
if (measurementId && measurementId !== PLACEHOLDER) {
  config.measurementId = measurementId;
}

const output = `// AUTO-GENERATED — do not edit manually.
// Generated by scripts/generate-firebase-config.mjs at build time.
// Contains only PUBLIC Firebase project identifiers (safe for the browser).
// Server secrets must never appear here.
/* eslint-disable */
self.__FIREBASE_CONFIG__ = ${JSON.stringify(config, null, 2)};
`;

const outPath = path.join(ROOT, 'public', 'firebase-config.js');
fs.writeFileSync(outPath, output, 'utf8');
console.log(`✅ Firebase config written to ${outPath}`);
